(function () {
  // Installed after navigation; this observes responses generated by the page's own scrolling.
  // No authentication values, cookies or private browser state are read.
  if (!window.__xbatchScroll) {
    const state = window.__xbatchScroll = { responses: [], pending: 0 };
    const save = (url, text) => {
      try {
        const u = new URL(url, location.href);
        if (u.origin === location.origin && u.pathname.includes('/graphql/') && text.length < 2000000) {
          JSON.parse(text);
          if (state.responses.length < 20) state.responses.push(text);
        }
      } catch (_) {}
    };
    const originalFetch = window.fetch;
    window.fetch = function (...args) {
      state.pending++;
      return originalFetch.apply(this, args).then(response => {
        response.clone().text().then(text => save(response.url, text)).catch(() => {});
        return response;
      }).finally(() => { state.pending--; });
    };
    const originalSend = XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.send = function (...args) {
      state.pending++;
      this.addEventListener('loadend', () => {
        state.pending--;
        try { save(this.responseURL, this.responseText); } catch (_) {}
      }, { once: true });
      return originalSend.apply(this, args);
    };
  }
  const target = __USERNAME__;
  const items = [], posts = new Set();
  const status = href => {
    try {
      const u = new URL(href, location.href);
      if (!['x.com', 'twitter.com'].includes(u.hostname)) return null;
      const m = u.pathname.match(/^\/([\w]+)\/status\/(\d+)(?:\/|$)/);
      return m ? { user: m[1], id: m[2], path: u.pathname } : null;
    } catch (_) { return null; }
  };
  for (const article of document.querySelectorAll('article')) {
    const container = article.closest('[data-testid="cellInnerDiv"]') || article.parentElement;
    if (!container) continue;
    const references = [...container.querySelectorAll('a[href]')].map(a => status(a.href)).filter(Boolean);
    const own = references.filter(r => r.user.toLowerCase() === target.toLowerCase());
    own.forEach(r => posts.add(r.id));
    // Be conservative: mixed post IDs may be a quote, embedded post or a recommendation.
    const ids = new Set(references.map(r => r.id));
    if (!own.length || ids.size !== 1) continue;
    const context = container.querySelector('[data-testid="socialContext"]');
    if (context && /repost|retweet|转帖|转发/i.test(context.textContent || '')) continue;
    if (article.querySelector('blockquote,[data-testid="quoteTweet"]')) continue;
    for (const link of article.querySelectorAll('a[href*="/photo/"]')) {
      const ref = status(link.href);
      if (!ref || ref.user.toLowerCase() !== target.toLowerCase() || ref.id !== own[0].id) continue;
      for (const img of link.querySelectorAll('img')) {
        if (img.closest('article') !== article) continue;
        const src = img.currentSrc || img.src;
        if (!src.startsWith('https://pbs.twimg.com/media/')) continue;
        items.push({ post_id: ref.id, raw_url: src });
      }
    }
  }
  const state = window.__xbatchScroll;
  const result = { posts: [...posts], items, responses: state.responses.splice(0), pending: state.pending,
    url: location.href, height: document.scrollingElement?.scrollHeight || 0 };
  window.scrollBy(0, Math.max(500, window.innerHeight * 0.8));
  return JSON.stringify(result);
})();
